"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["99660"],{7579(e,t,r){r.r(t),r.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>c,contentTitle:()=>d,toc:()=>h,assets:()=>p});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-product-delink","title":"De-link payer product","description":"Removes a product (product id and name) from a payer\'s participant code in the registry.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-product-delink.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-product-delink","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/endpoints/registry-product-delink","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"De-link payer product","sidebar_label":"De-link payer product","sidebar_class_name":"api-method api-method--post","description":"Removes a product (product id and name) from a payer\'s participant code in the registry.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Link payer product","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/endpoints/registry-product-link"},"next":{"title":"Get product owner","permalink":"/docs/pr-13/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner"}}'),i=r(62540),a=r(43023),o=r(44136),s=JSON.parse('{"id":"registry_product_delink","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/product/delink","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"De-link payer product","description":"Removes a product (product id and name) from a payer\'s participant code in the registry.\\n\\n### Business purpose\\n\\nWhen a payer withdraws a product from the market or replaces it, the registry entry created by /product/link should be removed so that it is no longer resolvable and cannot be referenced by new member links. The OpenAPI document describes this Retrieving API call as the API to de-link products by the payers or insurance companies. Keeping the catalogue accurate protects providers from matching on retired products when they resolve coverage for InsurancePlan and preauthorisation.\\n\\n### When to use\\n\\nUse it when a product is discontinued or renamed (the docs give no rename operation, so de-link and re-link), after the member links that reference it have been handled through /participant/delink/abha/policy. It is a payer-side catalogue maintenance step and is not tied to any claim workflow code. The documentation does not state whether de-linking a product that still has member links is refused, so remove member links first.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_id, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorization).\\n- Base path for the participant service: https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation id are involved.\\n- The payer or insurance company must already be a registered participant with its own participant code.\\n- Body is ProductLinkRequest with all three fields required: productid, productname and participantcode.\\n\\n### Postconditions\\n\\nOn success the endpoint returns HTTP 200 with ParticipantCreateResponse containing the optional participant_code. No callback follows. The product should no longer resolve to the payer through /product/getowner. Failures return 400, 404 or 500 with the ErrorResponse envelope. Provider-side policy caches are documented as permanent, so a product that hospitals have already cached will still appear there until they pass forceRefresh: true.\\n\\n### Common mistakes\\n\\n- Sending only productid; ProductLinkRequest requires productid, productname and participantcode for de-link as well.\\n- De-linking a product while members are still linked to it, then finding those member links inconsistent; de-link members first.\\n- Using a participantcode from the wrong environment or with wrong casing.\\n- Assuming providers see the change immediately; their cached policies persist without TTL.\\n- Missing the Accept header or sending the token without the Bearer prefix.\\n\\n### Best practices\\n\\n- Enumerate and de-link affected member policies before removing the product.\\n- Use the exact productid and productname that were registered with /product/link.\\n- Verify afterwards with /product/getowner that the product no longer resolves to your participant code.\\n- Log the request and the returned participant_code for audit.\\n- Refresh the Bearer token proactively and retry once on 401.\\n\\n### Related scenario\\n\\nAn insurer retires its old Individual Health Silver product at the end of a policy year, having migrated every member to a successor product. Its system first runs /participant/delink/abha/policy for each member still linked to the old product, then calls /product/delink with the product id, product name and the insurer\'s participant code. A confirmation call to /product/getowner shows the product no longer resolves. The insurer notifies its network hospitals, whose desks force a refresh of cached policies so that the next coverage-eligibility check and preauthorisation reference the successor product.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"productid","type":"string","required":false,"description":"","encrypted":false},{"name":"productname","type":"string","required":false,"description":"","encrypted":false},{"name":"participantcode","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"productid":"PRD-INDIV-07","productname":"Individual Health Silver","participantcode":"100234@sbx"},"responses":[{"status":"200","description":"On success the endpoint returns HTTP 200 with ParticipantCreateResponse containing the optional participant_code.","example":{"participant_code":"100234@sbx"}}],"tag":"Participant registry","tagDescription":"Every NHCX API call, whether a registry lookup, a certificate fetch or a claim submission, is rejected unless it carries a valid Bearer token, so this is the first call any integration makes and the first thing to check when a working integration starts failing.","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/delink \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-INDIV-07\\",\\n  \\"productname\\": \\"Individual Health Silver\\",\\n  \\"participantcode\\": \\"100234@sbx\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/delink \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-INDIV-07\\",\\n  \\"productname\\": \\"Individual Health Silver\\",\\n  \\"participantcode\\": \\"100234@sbx\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/delink\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"productid\\": \\"PRD-INDIV-07\\",\\n        \\"productname\\": \\"Individual Health Silver\\",\\n        \\"participantcode\\": \\"100234@sbx\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/delink\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"productid\\": \\"PRD-INDIV-07\\",\\n    \\"productname\\": \\"Individual Health Silver\\",\\n    \\"participantcode\\": \\"100234@sbx\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let c={title:"De-link payer product",sidebar_label:"De-link payer product",sidebar_class_name:"api-method api-method--post",description:"Removes a product (product id and name) from a payer's participant code in the registry.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"nhcx-registry.yaml",generated:!0},d,p={},h=[];function l(e){return(0,i.jsx)(o.A,{operation:s})}function u(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}}}]);